import pathlib, base64
B=pathlib.Path("src/frontend")
def w(n,c):
    (B/n).write_text(c,encoding="utf-8")
    print(f"{n}: {len(c)} bytes")

SIM_TRAINING_B64 = ""
w("sim-training.html", base64.b64decode(SIM_TRAINING_B64).decode("utf-8"))

ENERGY_COMPLIANCE_B64 = ""
w("energy-compliance.html", base64.b64decode(ENERGY_COMPLIANCE_B64).decode("utf-8"))

SAFETY_EMERGENCY_B64 = ""
w("safety-emergency.html", base64.b64decode(SAFETY_EMERGENCY_B64).decode("utf-8"))

SHIP_SHORE_B64 = ""
w("ship-shore.html", base64.b64decode(SHIP_SHORE_B64).decode("utf-8"))
